-- GENERATED by scripts/build_catalog.py from supabase/catalog/catalog.json. Do not edit by hand.
-- Demo venues, cafes, menus and photo credits. Invented content is listed in the README.

on conflict (id) do update set
  name = excluded.name, address = excluded.address, city = excluded.city, country = excluded.country,
  cover_image_url = excluded.cover_image_url, logo_url = excluded.logo_url, subtitle = excluded.subtitle,
  kind = excluded.kind, is_open = excluded.is_open, is_active = excluded.is_active,
  latitude = excluded.latitude, longitude = excluded.longitude, group_name = excluded.group_name;

on conflict (id) do update set
  name = excluded.name, floor_label = excluded.floor_label, block_label = excluded.block_label,
  average_wait_seconds = excluded.average_wait_seconds, is_open = excluded.is_open;

on conflict (id) do update set title = excluded.title, sort_order = excluded.sort_order;

on conflict (id) do update set
  category_id = excluded.category_id, title = excluded.title, subtitle = excluded.subtitle,
  volume_label = excluded.volume_label, image_url = excluded.image_url, price_cents = excluded.price_cents,
  is_available = excluded.is_available, sort_order = excluded.sort_order;

on conflict (menu_item_id, allergen) do nothing;

on conflict (id) do update set title = excluded.title, is_required = excluded.is_required,
  allows_multiple = excluded.allows_multiple, sort_order = excluded.sort_order;

on conflict (id) do update set title = excluded.title, price_delta_cents = excluded.price_delta_cents, sort_order = excluded.sort_order;

on conflict do nothing;

on conflict (image_key) do update set title = excluded.title, author = excluded.author,
  license = excluded.license, license_url = excluded.license_url, source_url = excluded.source_url;
